#!/usr/bin/env node
/**
 * Playwright functional matrix for the interactive chart.
 *
 * Covers all 11 enabled timeframes at 1600x1000 and 390x844, the VWAP/SMA200
 * availability gates, the all-on indicator counts/chips, switching, and an
 * out-of-order response race. Writes PNGs + JSON to the artifact dir (or --out).
 *
 * Prerequisites: a preview server on 127.0.0.1:4174 and fixtures generated by
 * `bun run perf:chart:fixtures`. See docs/CHART_PERFORMANCE.md.
 */
import { chromium } from "@playwright/test";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const BASE_URL = arg("base-url", process.env.CHART_PERF_BASE_URL ?? "http://127.0.0.1:4174").replace(/\/$/, "");
const ARTIFACT_ROOT =
  process.env.CHART_PERF_ARTIFACT_DIR ||
  (process.env.CODESPACES ? "/workspaces/react/.agent-artifacts/chart-perf" : "/tmp/opencode/chart-perf");
const FIXTURES_DIR = arg("fixtures", join(ARTIFACT_ROOT, "fixtures"));
const OUT_DIR = arg("out", join(ARTIFACT_ROOT, "matrix"));
const HEADED = process.argv.includes("--headed");
const VIEWPORTS = [
  { name: "1600x1000", width: 1600, height: 1000 },
  { name: "390x844", width: 390, height: 844 },
];
const TF_IDS = ["1m", "5m", "10m", "15m", "30m", "1h", "3h", "4h", "1D", "1W", "1M"];
const DEFAULT_TF = "1D";
const USER = {
  id: 1,
  email: "perf@local",
  display_name: "Perf",
  initial_capital: 1000000,
  created_at: "2026-01-01T00:00:00",
};

function arg(name, fallback) {
  const index = process.argv.indexOf(`--${name}`);
  if (index === -1) return fallback;
  const value = process.argv[index + 1];
  return value && !value.startsWith("--") ? value : fallback;
}

function fail(message) {
  console.error(`chart matrix: ${message}`);
  process.exit(1);
}

function sleep(ms) {
  return new Promise((done) => setTimeout(done, ms));
}

function loadFixtures() {
  const path = join(FIXTURES_DIR, "fixtures.json");
  if (!existsSync(path)) {
    fail(
      `missing ${path}. Generate real fixtures first:\n` +
        "  bun run perf:chart:fixtures",
    );
  }
  const data = JSON.parse(readFileSync(path, "utf8"));
  const ids = Object.keys(data.timeframes ?? {});
  if (ids.length !== 11) {
    fail(`expected 11 fixture timeframes, got ${ids.length}: ${ids.join(", ")}`);
  }
  return data;
}

async function preflight() {
  let response;
  try {
    response = await fetch(`${BASE_URL}/`);
  } catch (error) {
    fail(
      `no server at ${BASE_URL} (${error.message}). ` +
        "Run `bun run build` and `bun run preview -- --host 127.0.0.1 --port 4174`.",
    );
  }
  if (!response.ok) fail(`${BASE_URL}/ returned HTTP ${response.status}`);
}

async function installAuth(context) {
  await context.addInitScript((user) => {
    localStorage.setItem("alphashri_token", "chart_perf_opaque_token");
    localStorage.setItem("alphashri_refresh_token", "chart_perf_opaque_refresh");
    localStorage.setItem("alphashri_user", JSON.stringify(user));
  }, USER);
}

async function installMocks(context, fixtures, options = {}) {
  const chartBodies = {};
  const requestLog = [];
  const tfSpecs = Object.keys(fixtures.timeframes).map((id) => ({ id, label: id }));

  // Catch-all first: each later route wins for its own pattern.
  await context.route("**/api/**", (route) =>
    route.fulfill({ status: 200, contentType: "application/json", body: "{}" }),
  );
  await context.route("**/api/auth/me", (route) =>
    route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(USER) }),
  );
  await context.route("**/api/auth/refresh", (route) =>
    route.fulfill({
      status: 401,
      contentType: "application/json",
      body: JSON.stringify({ detail: "refresh disabled in perf harness" }),
    }),
  );
  await context.route("**/api/chart-patterns/timeframes**", (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify({ timeframes: tfSpecs }),
    }),
  );
  await context.route("**/api/chart-patterns/symbol/*/chart**", async (route) => {
    const url = new URL(route.request().url());
    const requested = url.searchParams.get("timeframe") || DEFAULT_TF;
    const tf = fixtures.timeframes[requested] ? requested : DEFAULT_TF;
    const fixture = fixtures.timeframes[tf];
    const delayed = options.delayTf === tf;
    requestLog.push({ tf, event: "request", at: Date.now() });
    if (delayed) await sleep(options.delayMs ?? 1200);

    const short = options.shortBarsTf === tf;
    const candles = short
      ? fixture.candles.slice(-(options.shortBars ?? 120))
      : fixture.candles;
    const body = JSON.stringify({
      symbol: fixtures.symbol,
      timeframe: tf,
      candles,
      overlays: [],
      trend_lines: [],
      hits: [],
      indicators: short ? null : fixture.indicators,
      sr_zones: short ? [] : fixture.sr_zones,
    });
    chartBodies[tf] = body;
    requestLog.push({ tf, event: "fulfil", at: Date.now() });
    await route.fulfill({ status: 200, contentType: "application/json", body });
  });

  return { chartBodies, requestLog };
}

async function waitForTimeframeOptions(page) {
  await page.waitForFunction(
    (ids) => {
      const select = document.querySelector(
        '[data-testid="patterns-timeframe-select"] select',
      );
      if (!(select instanceof HTMLSelectElement)) return false;
      const values = new Set([...select.options].map((option) => option.value));
      return ids.every((id) => values.has(id));
    },
    TF_IDS,
    { timeout: 20000 },
  );
}

async function waitForChart(page, tf, timeout = 25000) {
  await page.waitForSelector('[data-testid="patterns-tv-chart"] canvas', {
    state: "visible",
    timeout,
  });
  await page.waitForFunction(
    (expected) => {
      const select = document.querySelector(
        '[data-testid="patterns-timeframe-select"] select',
      );
      if (!(select instanceof HTMLSelectElement) || select.value !== expected) return false;
      if (document.querySelector('[data-testid="chart-error"]')) return false;
      if (document.querySelector('[data-testid="chart-empty"]')) return false;
      const loader = document.querySelector('[data-testid="patterns-fullscreen-loading"]');
      if (loader && loader.getBoundingClientRect().width > 0) return false;
      return true;
    },
    tf,
    { timeout },
  );
  await page.waitForTimeout(120);
}

async function selectTimeframe(page, tf) {
  const select = page.locator('[data-testid="patterns-timeframe-select"] select');
  await select.selectOption(tf);
  await waitForChart(page, tf);
}

async function openIndicators(page) {
  await page.locator('[data-testid="patterns-chart-indicators-trigger"]').click();
  await page
    .locator('[data-testid="patterns-chart-indicators-popover"]')
    .waitFor({ state: "visible", timeout: 5000 });
}

async function closeIndicators(page) {
  const popover = page.locator('[data-testid="patterns-chart-indicators-popover"]');
  if (await popover.isVisible().catch(() => false)) {
    await page.locator('[data-testid="patterns-chart-indicators-trigger"]').click();
    await popover.waitFor({ state: "hidden", timeout: 5000 });
  }
}

async function readIndicator(page, id) {
  return page.locator(`[data-testid="chart-indicator-${id}"]`).evaluate(
    (el, indicatorId) => {
      const input = /** @type {HTMLInputElement} */ (el);
      const group = input.closest("label");
      const reason = group?.querySelector(
        `[data-testid="chart-indicator-${indicatorId}-reason"]`,
      );
      return {
        disabled: Boolean(input.disabled),
        checked: Boolean(input.checked),
        reason: reason?.textContent?.trim() || null,
      };
    },
    id,
  );
}

async function enabledIndicatorIds(page) {
  return page.locator('input[data-testid^="chart-indicator-"]').evaluateAll((els) =>
    els
      .filter((el) => !/** @type {HTMLInputElement} */ (el).disabled)
      .map((el) => el.getAttribute("data-testid").replace("chart-indicator-", "")),
  );
}

async function waitForActiveCount(page, expected) {
  await page
    .waitForFunction(
      (want) => {
        const trigger = document.querySelector(
          '[data-testid="patterns-chart-indicators-trigger"]',
        );
        return Number(trigger?.getAttribute("data-active-count") ?? -1) === want;
      },
      expected,
      { timeout: 3000 },
    )
    .catch(() => {});
}

async function activeCounts(page) {
  const trigger = page.locator('[data-testid="patterns-chart-indicators-trigger"]');
  const triggerCount = Number((await trigger.getAttribute("data-active-count")) ?? 0);
  const strip = page.locator('[data-testid="chart-active-indicators"]');
  const stripVisible = (await strip.count()) > 0;
  const stripCount = stripVisible
    ? Number((await strip.getAttribute("data-active-count")) ?? 0)
    : 0;
  const chips = stripVisible
    ? await strip
        .locator("[data-indicator]")
        .evaluateAll((els) =>
          els
            .filter((el) => el.getAttribute("data-indicator") !== "overflow")
            .map((el) => el.getAttribute("data-indicator")),
        )
    : [];
  const overflowEl = stripVisible ? strip.locator('[data-indicator="overflow"]') : null;
  const overflowText = overflowEl && (await overflowEl.count())
    ? ((await overflowEl.first().textContent()) ?? "")
    : "";
  const overflow = Number(overflowText.replace(/[^0-9]/g, "") || 0);
  return { triggerCount, stripCount, chips, overflow };
}

async function gotoChart(page) {
  await page.goto(`${BASE_URL}/chart/POWERGRID.NS?tf=${DEFAULT_TF}`, {
    waitUntil: "domcontentloaded",
  });
  await waitForTimeframeOptions(page);
  await waitForChart(page, DEFAULT_TF);
}

async function capture(page, outDir, name) {
  const path = join(outDir, `${name}.png`);
  await page.screenshot({ path });
  return path;
}

async function runViewport(browser, fixtures, viewport, failures, result) {
  const outDir = join(OUT_DIR, viewport.name);
  mkdirSync(outDir, { recursive: true });
  const context = await browser.newContext({
    viewport: { width: viewport.width, height: viewport.height },
    deviceScaleFactor: 1,
  });
  await installAuth(context);
  const { chartBodies, requestLog } = await installMocks(context, fixtures);
  const page = await context.newPage();
  const viewportResult = {
    viewport: { width: viewport.width, height: viewport.height },
    timeframes: [],
    gating: {},
    all_on: null,
    stale_race: null,
  };

  try {
    await gotoChart(page);
    for (const tf of TF_IDS) {
      const before = requestLog.filter((entry) => entry.event === "fulfil").length;
      await selectTimeframe(page, tf);
      const after = requestLog.filter((entry) => entry.event === "fulfil").length;
      const screenshot = await capture(page, outDir, `${tf}`);
      const selectValue = await page
        .locator('[data-testid="patterns-timeframe-select"] select')
        .inputValue();
      const entry = {
        id: tf,
        select_value: selectValue,
        chart_requests: after - before,
        payload_bars: JSON.parse(chartBodies[tf] ?? "{}").candles?.length ?? 0,
        screenshot,
      };
      viewportResult.timeframes.push(entry);
      if (selectValue !== tf) failures.push(`${viewport.name}: ${tf} select value is ${selectValue}`);
      if (!chartBodies[tf]) failures.push(`${viewport.name}: ${tf} never received a chart payload`);
    }

    // VWAP must be intraday-only; SMA200 must be available with a full fixture.
    await selectTimeframe(page, DEFAULT_TF);
    await openIndicators(page);
    const dailyVwap = await readIndicator(page, "vwap");
    const dailySma200 = await readIndicator(page, "sma200");
    const dailyShot = await capture(page, outDir, "gating-1D");
    await closeIndicators(page);
    viewportResult.gating["1D"] = { vwap: dailyVwap, sma200: dailySma200, screenshot: dailyShot };
    if (!dailyVwap.disabled || !/intraday/i.test(dailyVwap.reason ?? "")) {
      failures.push(`${viewport.name}: 1D VWAP should be disabled with an intraday reason`);
    }

    await selectTimeframe(page, "5m");
    await openIndicators(page);
    const intradayVwap = await readIndicator(page, "vwap");
    const intradaySma200 = await readIndicator(page, "sma200");
    const intradayShot = await capture(page, outDir, "gating-5m");
    viewportResult.gating["5m"] = {
      vwap: intradayVwap,
      sma200: intradaySma200,
      screenshot: intradayShot,
    };
    if (intradayVwap.disabled) {
      failures.push(`${viewport.name}: 5m VWAP should be enabled when the payload carries a series`);
    }
    if (intradaySma200.disabled) {
      failures.push(`${viewport.name}: 5m SMA200 should be enabled with 500 fixture bars`);
    }

    // All-on is exercised on an intraday frame so VWAP is drawable too.
    const enabled = await enabledIndicatorIds(page);
    for (const id of enabled) {
      const input = page.locator(`[data-testid="chart-indicator-${id}"]`);
      if (!(await input.isChecked())) await input.click();
    }
    await waitForActiveCount(page, enabled.length);
    const countsOn = await activeCounts(page);
    const allOnShot = await capture(page, outDir, "all-on");
    viewportResult.all_on = {
      enabled_rows: enabled.length,
      trigger_count: countsOn.triggerCount,
      strip_count: countsOn.stripCount,
      chips: countsOn.chips,
      overflow: countsOn.overflow,
      screenshot: allOnShot,
    };
    if (countsOn.triggerCount !== enabled.length) {
      failures.push(
        `${viewport.name}: all-on trigger count ${countsOn.triggerCount} != enabled rows ${enabled.length}`,
      );
    }
    if (countsOn.stripCount !== countsOn.triggerCount) {
      failures.push(
        `${viewport.name}: all-on strip count ${countsOn.stripCount} != trigger count ${countsOn.triggerCount}`,
      );
    }
    const crosses = enabled.includes("crosses");
    const expectedChips = countsOn.triggerCount - (crosses ? 1 : 0);
    if (countsOn.chips.length + countsOn.overflow !== expectedChips) {
      failures.push(
        `${viewport.name}: all-on chips ${countsOn.chips.length}+${countsOn.overflow} != ${expectedChips}`,
      );
    }
    if (!countsOn.chips.includes("vwap")) {
      failures.push(`${viewport.name}: 5m all-on chips did not include VWAP`);
    }
    for (const id of enabled) {
      const input = page.locator(`[data-testid="chart-indicator-${id}"]`);
      if (await input.isChecked()) await input.click();
    }
    await waitForActiveCount(page, 0);
    const countsOff = await activeCounts(page);
    viewportResult.all_on.off_trigger_count = countsOff.triggerCount;
    if (countsOff.triggerCount !== 0) {
      failures.push(`${viewport.name}: all-off trigger count ${countsOff.triggerCount} != 0`);
    }
    await closeIndicators(page);
  } finally {
    await context.close();
  }

  // SMA200 gating needs fewer than 200 bars; isolate it from the real fixture.
  const shortContext = await browser.newContext({
    viewport: { width: viewport.width, height: viewport.height },
    deviceScaleFactor: 1,
  });
  await installAuth(shortContext);
  await installMocks(shortContext, fixtures, { shortBarsTf: "1W", shortBars: 120 });
  const shortPage = await shortContext.newPage();
  try {
    await shortPage.goto(`${BASE_URL}/chart/POWERGRID.NS?tf=1W`, {
      waitUntil: "domcontentloaded",
    });
    await waitForTimeframeOptions(shortPage);
    await waitForChart(shortPage, "1W");
    await openIndicators(shortPage);
    const sma200 = await readIndicator(shortPage, "sma200");
    const screenshot = await capture(shortPage, outDir, "gating-short-bars");
    viewportResult.gating.short_bars = { tf: "1W", bars: 120, sma200, screenshot };
    if (!sma200.disabled || !/200/.test(sma200.reason ?? "")) {
      failures.push(`${viewport.name}: SMA200 should require 200 bars on a 120-bar frame`);
    }
  } finally {
    await shortContext.close();
  }

  // Out-of-order responses: 5m is delayed, 15m resolves first.
  const raceContext = await browser.newContext({
    viewport: { width: viewport.width, height: viewport.height },
    deviceScaleFactor: 1,
  });
  await installAuth(raceContext);
  const raceMock = await installMocks(raceContext, fixtures, {
    delayTf: "5m",
    delayMs: 1400,
  });
  const racePage = await raceContext.newPage();
  try {
    await gotoChart(racePage);
    await racePage
      .locator('[data-testid="patterns-timeframe-select"] select')
      .selectOption("5m");
    // Ensure the delayed request is actually in flight before switching again.
    for (let attempt = 0; attempt < 50; attempt += 1) {
      if (raceMock.requestLog.some((entry) => entry.tf === "5m" && entry.event === "request")) {
        break;
      }
      await sleep(20);
    }
    await racePage
      .locator('[data-testid="patterns-timeframe-select"] select')
      .selectOption("15m");
    await waitForChart(racePage, "15m");
    await sleep(1600);
    const finalValue = await racePage
      .locator('[data-testid="patterns-timeframe-select"] select')
      .inputValue();
    const errorVisible = await racePage
      .locator('[data-testid="chart-error"]')
      .isVisible()
      .catch(() => false);
    const screenshot = await capture(racePage, outDir, "stale-race");
    const fulfils = raceMock.requestLog
      .filter((entry) => entry.event === "fulfil" && (entry.tf === "5m" || entry.tf === "15m"))
      .map((entry) => entry.tf);
    viewportResult.stale_race = {
      final_value: finalValue,
      error_visible: errorVisible,
      fulfil_order: fulfils,
      screenshot,
    };
    if (finalValue !== "15m" || errorVisible) {
      failures.push(
        `${viewport.name}: stale-race ended at ${finalValue} (error=${errorVisible}), expected 15m`,
      );
    }
    if (fulfils.lastIndexOf("15m") > fulfils.lastIndexOf("5m")) {
      failures.push(`${viewport.name}: race did not exercise an out-of-order response`);
    }
  } finally {
    await raceContext.close();
  }

  result.viewports.push(viewportResult);
}

async function main() {
  await preflight();
  const fixtures = loadFixtures();
  mkdirSync(OUT_DIR, { recursive: true });

  const browser = await chromium.launch({ headless: !HEADED });
  const failures = [];
  const result = {
    schema_version: 1,
    generated_at: new Date().toISOString(),
    harness: "scripts/perf/chart_tf_matrix.mjs",
    base_url: BASE_URL,
    fixtures_dir: FIXTURES_DIR,
    fixture: {
      symbol: fixtures.symbol,
      as_of: fixtures.as_of,
      timeframes: Object.keys(fixtures.timeframes),
    },
    viewports: [],
    failures,
  };

  try {
    for (const viewport of VIEWPORTS) {
      await runViewport(browser, fixtures, viewport, failures, result);
    }
  } finally {
    await browser.close();
  }

  const resultPath = join(OUT_DIR, "chart-tf-matrix.json");
  writeFileSync(resultPath, `${JSON.stringify(result, null, 2)}\n`);
  console.log(`chart matrix: ${failures.length ? "FAIL" : "PASS"} -> ${resultPath}`);
  for (const failure of failures) console.error(`  - ${failure}`);
  process.exit(failures.length ? 1 : 0);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
